WITH enriched AS (SELECT *, SUM(amount) OVER (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, CUME_DIST() OVER (PARTITION BY order_id, status ORDER BY amount NULLS FIRST) AS amount_cume_dist FROM payments) SELECT CASE WHEN amount_cume_dist >= 0.89 THEN 'LARGE' ELSE 'SMALL' END AS amount_cume_dist_tier, COUNT(DISTINCT method) AS distinct_methods, COUNT(DISTINCT order_id) AS distinct_order_ids, APPROX_PERCENTILE(amount_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS amount_cume_dist_quartiles, SUM(amount) AS total_amount FROM enriched GROUP BY amount_cume_dist_tier
